// A quiet, original 140 BPM pulse, synthesized locally after explicit consent.
export function createSound(){let ctx=null,master=null,timer=null,origin=0,next=0,step=0,on=false;const tempo=140,beat=60/tempo;
function tone(time,freq,duration,volume,type='sine'){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,time);g.gain.setValueAtTime(.0001,time);g.gain.exponentialRampToValueAtTime(volume,time+.009);g.gain.exponentialRampToValueAtTime(.0001,time+duration);o.connect(g);g.connect(master);o.start(time);o.stop(time+duration+.02);}
function kick(time){const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.setValueAtTime(115,time);o.frequency.exponentialRampToValueAtTime(44,time+.16);g.gain.setValueAtTime(.65,time);g.gain.exponentialRampToValueAtTime(.0001,time+.3);o.connect(g);g.connect(master);o.start(time);o.stop(time+.32);}
function hat(time){const count=Math.floor(ctx.sampleRate*.045),buf=ctx.createBuffer(1,count,ctx.sampleRate),d=buf.getChannelData(0);let seed=17;for(let i=0;i<count;i++){seed=(seed*16807)%2147483647;d[i]=(seed/2147483647*2-1)*(1-i/count);}const src=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),g=ctx.createGain();src.buffer=buf;filter.type='highpass';filter.frequency.value=7000;g.gain.value=.06;src.connect(filter);filter.connect(g);g.connect(master);src.start(time);}
function schedule(){if(!on)return;while(next<ctx.currentTime+.12){if(step%2===0)kick(next);else hat(next);if(step%4===2)tone(next,step%16<8?55:65.406,.15,.20,'triangle');next+=beat/2;step++;}}
return {async toggle(){if(on){on=false;clearInterval(timer);master.gain.setTargetAtTime(.0001,ctx.currentTime,.04);setTimeout(()=>{if(!on)ctx.suspend()},180);return false;}if(!ctx){const A=window.AudioContext||window.webkitAudioContext;if(!A)throw Error('Audio unavailable');ctx=new A();master=ctx.createGain();master.gain.value=.0001;master.connect(ctx.destination);}await ctx.resume();on=true;origin=ctx.currentTime;next=origin+.04;step=0;master.gain.setTargetAtTime(.12,ctx.currentTime,.1);schedule();timer=setInterval(schedule,25);return true;},pause(){if(on){on=false;clearInterval(timer);master.gain.setTargetAtTime(.0001,ctx.currentTime,.03);ctx.suspend();}},get active(){return on},get time(){return ctx?Math.max(0,ctx.currentTime-origin-.04):0}};
}
